package main
import("encoding/json";"go/ast";"go/parser";"go/token";"os";"path/filepath";"strings")
type Node struct{Name string `json:"name"`; Line int `json:"line"`; Doc string `json:"doc"`}
type Edge struct{From string `json:"from"`; To string `json:"to"`; Line int `json:"line"`}
type File struct{Name string `json:"name"`; Header string `json:"header"`; Functions []Node `json:"functions"`; Calls []Edge `json:"calls"`; Imports []string `json:"imports"`; Error string `json:"error,omitempty"`}
func target(e ast.Expr)string{switch n:=e.(type){case *ast.Ident:return n.Name;case *ast.SelectorExpr:return target(n.X)+"."+n.Sel.Name;case *ast.IndexExpr:return target(n.X)+"[动态键]";case *ast.CallExpr:return target(n.Fun)+"()";case *ast.FuncLit:return "匿名函数";case *ast.ParenExpr:return target(n.X);case *ast.StarExpr:return "*"+target(n.X)};return "动态调用"}
func main(){all:=[]File{};files,_:=filepath.Glob(filepath.Join(os.Args[1],"*.go"));for _,p:=range files{r:=File{Name:filepath.Base(p),Functions:[]Node{},Calls:[]Edge{},Imports:[]string{}};fset:=token.NewFileSet();f,err:=parser.ParseFile(fset,p,nil,parser.ParseComments);if err!=nil{r.Error=err.Error();all=append(all,r);continue};if len(f.Comments)>0{r.Header=f.Comments[0].Text()};for _,i:=range f.Imports{r.Imports=append(r.Imports,strings.Trim(i.Path.Value,"\""))};for _,d:=range f.Decls{if fn,ok:=d.(*ast.FuncDecl);ok{name:=fn.Name.Name;if fn.Recv!=nil&&len(fn.Recv.List)>0{name=target(fn.Recv.List[0].Type)+"."+name};doc:="";if fn.Doc!=nil{doc=fn.Doc.Text()};r.Functions=append(r.Functions,Node{name,fset.Position(fn.Pos()).Line,doc});ast.Inspect(fn.Body,func(n ast.Node)bool{if c,ok:=n.(*ast.CallExpr);ok{r.Calls=append(r.Calls,Edge{name,target(c.Fun),fset.Position(c.Pos()).Line})};return true})}};all=append(all,r)};json.NewEncoder(os.Stdout).Encode(all)}
